function makeBot(kind,options={}){const P=profileOf(kind,options);return(view,seat,rng)=>{if(!view||view.phase==='over'||seat<0)return null;if(view.phase==='place')return view.boards[seat]&&!view.boards[seat].placed&&view.boards[seat].alive?placeAction(view,seat,rng,P):null;if(view.turn!==seat)return null;return decide(view,seat,rng,P);};}
